type instance ActionMarker SubmitDaysheetActionOperation = Types2.SubmitDaysheet
type instance ActionFieldSpecs SubmitDaysheetActionOperation =
    '[]

submitDaysheetActionFields :: ActionFields SubmitDaysheetActionOperation
submitDaysheetActionFields =
    noActionFields

submitDaysheetActionEvidence :: ActionEvidence SubmitDaysheetActionOperation
submitDaysheetActionEvidence =
    actionEvidence (SurfaceIR.HtmxActionIR "SubmitDaysheet" "submit-daysheet" [] [SurfaceIR.HtmxOption (SurfaceIR.HtmxActionMethodIR SurfaceIR.HtmxPostIR), SurfaceIR.HtmxOption (SurfaceIR.HtmxActionSwapIR (SurfaceIR.HtmxTypedSyntaxIR "none" [])), SurfaceIR.HtmxOption (SurfaceIR.HtmxActionSyncIR (SurfaceIR.HtmxTypedSyntaxIR "this:drop" []))])

submitDaysheetAction :: ActionFields SubmitDaysheetActionOperation -> FrontendSurfaceAction
submitDaysheetAction =
    frontendSurfaceActionFromEvidence submitDaysheetActionEvidence

data ViewDaysheetDateActionOperation

type instance ActionSurface ViewDaysheetDateActionOperation = AdapterSurfaceMarker (AdapterFamilySurface Types3.DaysheetAdapterFamily)
